// Generates src/lib/contract/stream-events.ts from the backend stream event JSON Schema.
// Source: first argument or CONTRACT_SOURCE, a URL or a file. Default: the committed copy.
// --check: generate from the committed copy and fail if the committed types differ.
import { readFile, writeFile, mkdir } from "node:fs/promises";
import { dirname } from "node:path";
import { compile } from "json-schema-to-typescript";

const SCHEMA_COPY = "contract/stream-events.schema.json";
const OUTPUT = "src/lib/contract/stream-events.ts";
const BANNER = [
  "// DO NOT EDIT. Generated by `npm run contract:generate` from",
  `// ${SCHEMA_COPY} (backend: GET /api/v1/schemas/stream-events.json).`,
].join("\n");

const args = process.argv.slice(2);
const check = args.includes("--check");
const source = check
  ? SCHEMA_COPY
  : (args.find((a) => !a.startsWith("--")) ?? (process.env.CONTRACT_SOURCE || SCHEMA_COPY));

async function loadSchema(from) {
  if (/^https?:\/\//.test(from)) {
    const response = await fetch(from, { signal: AbortSignal.timeout(10_000) });
    if (!response.ok) throw new Error(`GET ${from} returned ${response.status}`);
    return response.json();
  }
  return JSON.parse(await readFile(from, "utf8"));
}

// Pydantic titles every property; without this the generator emits aliases such as Type1 and Text1.
function dropPropertyTitles(node) {
  if (Array.isArray(node)) return node.map(dropPropertyTitles);
  if (node === null || typeof node !== "object") return node;
  const out = Object.fromEntries(Object.entries(node).map(([k, v]) => [k, dropPropertyTitles(v)]));
  if (out.properties) {
    for (const prop of Object.values(out.properties)) delete prop.title;
  }
  return out;
}

const schema = await loadSchema(source);
const types = await compile(dropPropertyTitles(schema), "StreamEvent", {
  bannerComment: BANNER,
  additionalProperties: false,
});

if (check) {
  const committed = await readFile(OUTPUT, "utf8").catch(() => null);
  if (committed?.replaceAll("\r\n", "\n") !== types) {
    console.error(`${OUTPUT} does not match ${SCHEMA_COPY}. Run: npm run contract:generate`);
    process.exit(1);
  }
  console.log(`${OUTPUT} matches ${SCHEMA_COPY}`);
} else {
  if (source !== SCHEMA_COPY) {
    await mkdir(dirname(SCHEMA_COPY), { recursive: true });
    await writeFile(SCHEMA_COPY, JSON.stringify(schema, null, 2) + "\n");
    console.log(`wrote ${SCHEMA_COPY} from ${source}`);
  }
  await mkdir(dirname(OUTPUT), { recursive: true });
  await writeFile(OUTPUT, types);
  console.log(`wrote ${OUTPUT}`);
}
